-- =================================================================
-- Migration: 007_barangay.sql
-- Purpose:   Create the barangay_clearances table for the Barangay Module.
-- Author:    eBPLS Team
-- Policy:    RBAC — only Barangay_Officer role may update clearance status.
--            Clearance number is generated by the API service on issuance.
--            Remarks are mandatory when rejecting a clearance request.
--            RLS enforcement deferred to 013_rls_policies.sql.
-- =================================================================

CREATE TABLE IF NOT EXISTS public.barangay_clearances (
    id               UUID         PRIMARY KEY DEFAULT gen_random_uuid(),

    -- Link to the parent permit application
    application_no   VARCHAR(20)  NOT NULL REFERENCES public.applications (application_no) ON DELETE CASCADE,

    -- Type of clearance being requested (FK to lookup defined in 006_verifications.sql)
    clearance_type_id INTEGER     NOT NULL REFERENCES public.clearance_types (id),

    -- Clearance status: Pending=awaiting action, Issued=approved, Rejected=denied
    -- Using a CHECK constraint here (not ENUM) as this is a small,
    -- module-scoped status set that does not need a shared type.
    status           VARCHAR(20)  NOT NULL DEFAULT 'Pending'
                                  CHECK (status IN ('Pending', 'Issued', 'Rejected')),

    -- Government-issued clearance reference number.
    -- Format determined by the Barangay (e.g., BC-2026-00001).
    -- NULL until the Barangay Officer issues the clearance.
    clearance_no     VARCHAR(50)  UNIQUE,

    -- Remarks: mandatory when rejecting; optional notes when issuing.
    remarks          TEXT,

    -- The Barangay Officer who processed this clearance request.
    -- SET NULL on user deletion to preserve the clearance record.
    processed_by     UUID         REFERENCES public.users (user_id) ON DELETE SET NULL,

    -- Validity window — set by the Barangay Officer on issuance.
    -- Standard LGU practice: clearance valid for 1 year from issuance.
    issued_at        TIMESTAMPTZ,
    expires_at       TIMESTAMPTZ,

    created_at       TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at       TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    -- Business rule: one active clearance per application per clearance type.
    -- Prevents duplicate pending requests for the same document.
    UNIQUE (application_no, clearance_type_id)
);

COMMENT ON TABLE  public.barangay_clearances                   IS 'Barangay clearance requests and issuances linked to permit applications.';
COMMENT ON COLUMN public.barangay_clearances.application_no   IS 'FK to the parent application. Cascades on application deletion.';
COMMENT ON COLUMN public.barangay_clearances.clearance_no     IS 'Unique LGU-issued clearance number. NULL until Barangay Officer issues.';
COMMENT ON COLUMN public.barangay_clearances.status           IS 'Pending=awaiting officer action, Issued=approved and valid, Rejected=denied with remarks.';
COMMENT ON COLUMN public.barangay_clearances.remarks          IS 'Mandatory when rejecting. Optional notes when issuing. Visible to the applicant.';
COMMENT ON COLUMN public.barangay_clearances.processed_by     IS 'Barangay Officer who issued or rejected the clearance.';
COMMENT ON COLUMN public.barangay_clearances.issued_at        IS 'Timestamp of clearance issuance. NULL while still Pending or Rejected.';
COMMENT ON COLUMN public.barangay_clearances.expires_at       IS 'Clearance expiry date. Typically 1 year from issued_at. Set by the Barangay Officer.';

CREATE OR REPLACE TRIGGER barangay_clearances_set_updated_at
    BEFORE UPDATE ON public.barangay_clearances
    FOR EACH ROW
    EXECUTE FUNCTION public.set_updated_at();
